/**
 * Panel styles for the right Sidebar's narrow column.
 *
 * Every token read carries the Host name first and a neutral fallback second,
 * so the panel keeps its layout and stays legible even before a theme defines
 * the aliases.
 */
/** The stylesheet this plugin installs for the lifetime of its Client run. */
export declare const STYLES = "\n.gt-root {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  min-height: 0;\n  background: var(--dsw-alias-bg-base, #ffffff);\n  color: var(--dsw-alias-label-primary, #1f2328);\n  font-size: 13px;\n  line-height: 1.5;\n}\n.gt-header {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 8px 10px 6px;\n}\n.gt-java {\n  display: inline-flex;\n  flex: 1 1 auto;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n  padding: 3px 8px;\n  border: 1px solid var(--dsw-alias-border-l2, #d0d7de);\n  border-radius: 6px;\n  background: var(--dsw-alias-bg-layer-1, #ffffff);\n}\n.gt-java-label {\n  color: var(--dsw-alias-label-secondary, #6b7280);\n  font-size: 12px;\n}\n.gt-select {\n  flex: 1 1 auto;\n  min-width: 0;\n  padding: 2px 0;\n  border: 0;\n  background: transparent;\n  color: inherit;\n  font: inherit;\n  font-size: 12px;\n  cursor: pointer;\n}\n.gt-select:focus {\n  outline: none;\n}\n.gt-icon-button {\n  display: inline-flex;\n  flex: 0 0 auto;\n  align-items: center;\n  justify-content: center;\n  width: 26px;\n  height: 26px;\n  padding: 0;\n  border: 1px solid var(--dsw-alias-border-l2, #d0d7de);\n  border-radius: 6px;\n  background: var(--dsw-alias-bg-layer-1, #ffffff);\n  color: var(--dsw-alias-label-secondary, #6b7280);\n  cursor: pointer;\n}\n.gt-icon-button:hover:not(:disabled) {\n  background: var(--dsw-alias-bg-layer-2, #f3f4f6);\n  color: var(--dsw-alias-label-primary, #1f2328);\n}\n.gt-icon-button:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n}\n.gt-icon-button.gt-icon-button-on {\n  border-color: var(--dsw-alias-brand-primary, #2563eb);\n  background: color-mix(in srgb, var(--dsw-alias-brand-primary, #2563eb) 16%, transparent);\n  color: var(--dsw-alias-brand-primary, #2563eb);\n}\n.gt-hint {\n  padding: 0 10px 8px;\n  color: var(--dsw-alias-label-secondary, #6b7280);\n  font-size: 11.5px;\n  word-break: break-word;\n}\n.gt-hint-detail {\n  opacity: 0.8;\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 11px;\n}\n.gt-hint-launch {\n  margin-top: 4px;\n  color: var(--dsw-alias-state-success-primary, #15803d);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.gt-toolbar {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 6px 10px;\n  border-top: 1px solid var(--dsw-alias-border-l1, #e5e7eb);\n}\n.gt-filter {\n  flex: 1 1 auto;\n  min-width: 0;\n  padding: 4px 8px;\n  border: 1px solid var(--dsw-alias-border-l2, #d0d7de);\n  border-radius: 6px;\n  background: var(--dsw-alias-bg-base, #ffffff);\n  color: inherit;\n  font: inherit;\n  font-size: 12px;\n}\n.gt-scroll {\n  flex: 1 1 auto;\n  min-height: 0;\n  overflow: auto;\n  padding: 2px 6px 12px;\n}\n.gt-group-head {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  width: 100%;\n  padding: 4px 6px;\n  border: 0;\n  border-radius: 6px;\n  background: transparent;\n  color: var(--dsw-alias-label-secondary, #6b7280);\n  font: inherit;\n  font-size: 12px;\n  font-weight: 600;\n  text-align: left;\n  cursor: pointer;\n}\n.gt-group-head:hover {\n  background: var(--dsw-alias-bg-layer-2, #f3f4f6);\n}\n.gt-group-name {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.gt-caret {\n  display: inline-block;\n  width: 10px;\n  transition: transform 0.12s ease;\n}\n.gt-caret.gt-open {\n  transform: rotate(90deg);\n}\n.gt-count {\n  margin-left: auto;\n  font-weight: 400;\n  opacity: 0.75;\n}\n.gt-task {\n  display: block;\n  width: 100%;\n  box-sizing: border-box;\n  padding: 4px 8px 4px 22px;\n  border: 0;\n  border-radius: 6px;\n  background: transparent;\n  color: inherit;\n  font: inherit;\n  text-align: left;\n  cursor: pointer;\n}\n.gt-task:hover:not(:disabled) {\n  background: var(--dsw-alias-bg-layer-2, #f3f4f6);\n}\n.gt-task:disabled {\n  cursor: progress;\n  opacity: 0.6;\n}\n.gt-task.gt-selected {\n  background: var(--dsw-alias-bg-layer-2, #eef2ff);\n  box-shadow: inset 2px 0 0 var(--dsw-alias-brand-primary, #2563eb);\n}\n.gt-task-name {\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 12.5px;\n  word-break: break-word;\n}\n.gt-task-desc {\n  overflow: hidden;\n  color: var(--dsw-alias-label-secondary, #6b7280);\n  font-size: 11.5px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.gt-empty {\n  padding: 20px 12px;\n  color: var(--dsw-alias-label-secondary, #6b7280);\n  font-size: 12px;\n  text-align: center;\n}\n";
